from lib import *
S = SS('f115')
R = J('f115'); pf = R['perf']
steps = [
    step("dump(对象 → dict)只输出声明过的字段:对象上的 secret 没声明就不会出现,password 声明成 load_only 也不输出;data_key 把 name 输出成 fullName;Method 字段 display 是 \"ann <ann@x.test>\";Decimal 加 as_string=True 输出成字符串 \"10.50\";datetime 是 ISO 格式 2026-01-02T03:04:05;嵌套列表 posts 缺省是 []。", t=tl(S(1)), done=lidx(S(1), '对象上的 secret', 'data_key'), kv=KV([['只输出声明的字段', '不会泄漏 secret'], ['load_only', '不输出'], ['as_string', 'Decimal 变字符串']], ['load_only'])),
    step("load(dict → 数据)同时校验与转换:合法输入得到 {name, email, password, balance: Decimal('3.14')}(places=2 把 3.14159 量化成 3.14);什么都没给 → 三个必填字段各一条「Missing data for required field.」;多个字段同时出错一次全报(name 长度、email 格式);name 是数字 → 「Not a valid string.」;嵌套 posts 第 2 项缺 title → {posts: {\"1\": {title: [...]}}}(用下标定位);传了 dump_only 的 id → 「Unknown field.」。", t=tl(S(2)), done=lidx(S(2), '合法输入'), mark=lidx(S(2), '什么都没给', '多个字段', '类型不对', '嵌套', 'dump_only'), kv=KV([['错误结构', '按字段分组,嵌套用下标'], ['一次返回所有错误', '不是遇到第一个就停']], ['错误结构'])),
    step("未知字段:默认 unknown = RAISE,多余的 extra → {extra: [\"Unknown field.\"]};EXCLUDE 悄悄丢掉它(结果里没有 extra);INCLUDE 保留它(结果里有 extra: 1)。要不要接受客户端多传的字段,是需要明确决定的事。", t=tl(S(3)), mark=lidx(S(3), 'RAISE'), done=lidx(S(3), 'EXCLUDE', 'INCLUDE'), kv=KV([['RAISE', '报错(默认)'], ['EXCLUDE', '丢掉'], ['INCLUDE', '保留']], ['RAISE'])),
    step("部分更新与钩子:partial=True 时只给 name 也通过;@pre_load 去空格转小写加 @post_load 构造对象,\"  Ann \" 变成 name = ann 的 Range 对象;@validates('name') 对 \" ADMIN \"(先经 pre_load 变成 admin)报 {name: [\"保留名\"]};@validates_schema 做跨字段校验,start=9、end=1 报 {start: [\"start 必须小于等于 end\"]}(错误挂在指定的字段上)。", t=tl(S(4)), done=lidx(S(4), 'partial=True', 'pre_load'), mark=lidx(S(4), 'validates'), kv=KV([['partial=True', 'PATCH 部分更新'], ['pre_load / post_load', '预处理与构造对象'], ['validates_schema', '跨字段校验']], ['partial=True'])),
    step("类型转换比想象的宽松:Int 字段收到 5、'5'、5.0 → 5,收到 5.5 → 5(小数被截断,不报错),收到 ' 7 ' → 7;而 '5.0'、True、'abc' → 「Not a valid integer.」,None → 「Field may not be null.」。需要严格的整数时要设 strict=True,本篇没有验证它的效果。", t=tl(S(5)), mark=lidx(S(5), "'5.0'", 'True', "'abc'", 'None'), done=lidx(S(5), '5.5', "' 7 '"), kv=KV([['5.5', '→ 5(截断)'], ["'5'", '→ 5'], ['True', '错误']], ['5.5'])),
    step(f"性能:dump 10000 个对象,marshmallow {pf[0]:.1f} ms,手写字典推导 {pf[1]:.1f} ms,约 {pf[0] / pf[1]:.0f} 倍。Schema 带来校验、序列化规则和文档(见第 114 篇),但在大列表上不是免费的——热点接口的大列表要量一下再决定。", b=bars([['marshmallow dump', pf[0], f'{pf[0]:.1f} ms'], ['手写字典推导', max(pf[1], 0.5), f'{pf[1]:.1f} ms']], pf[0], mark=[0], done=[1]), t=tl(S(6)), done=lidx(S(6), '手写'), mark=lidx(S(6), 'marshmallow dump'), kv=KV([['marshmallow', f'{pf[0]:.1f} ms / 10000 个'], ['手写', f'{pf[1]:.1f} ms']], ['marshmallow'])),
]
A = mkartf('f115', 115, 'Flask,Marshmallow,序列化,校验,真实验证,动画演示',
    f'用 marshmallow 4.3.1 实测序列化与校验:dump 只输出声明的字段与 load_only、load 一次返回所有错误且嵌套用下标定位、未知字段的 RAISE 与 EXCLUDE 与 INCLUDE、partial 与钩子、Int 字段把 5.5 截断成 5、dump 10000 个对象比手写字典慢约 {pf[0] / pf[1]:.0f} 倍。',
    'Marshmallow 的 dump 与 load 各做了什么?错误信息长什么样?未知字段怎么处理?类型转换有多宽松?性能代价有多大?这篇逐项运行并打印每种情况的结果。',
    [('不泄漏', 'dump 只输出声明过的字段,没声明的 secret 与 load_only 的 password 都不会出现'), ('5.5 → 5', 'Int 字段把小数悄悄截断成整数'), (f'约 {pf[0] / pf[1]:.0f} 倍', 'dump 10000 个对象相对手写字典推导的耗时')],
    [('dump', '<p>上一篇:<a href="flask-openapi-generation.html">OpenAPI 文档生成</a>;下一篇:<a href="flask-pydantic-in-flask.html">Pydantic 在 Flask 中的使用</a>。</p>'), ('load 与错误结构', None), ('未知字段', None), ('部分更新与钩子', None), ('类型转换', None), ('性能', None)],
    steps, [ENV_F + '。marshmallow 4.3.1', '没有验证:strict=True 的行为、与 SQLAlchemy 模型集成的 marshmallow-sqlalchemy、自定义字段类型、上下文传参(marshmallow 4 的 context 变化)、与 webargs 的参数解析配合'], 'Marshmallow 序列化', panels=[('t', 'term', '实验输出'), ('b', 'bars', '耗时'), ('kv', 'kv', '要点')])
